import{_ as t,o as a,c as n,ag as o}from"./chunks/framework.Cu2CLAe3.js";const u=JSON.parse('{"title":"Type and value category","description":"Understanding the basics of the C++ type system, type conversion rules, and value categories","frontmatter":{"title":"Type and value category","description":"Understanding the basics of the C++ type system, type conversion rules, and value categories"},"headers":[],"relativePath":"en/vol1-fundamentals/ch01/index.md","filePath":"en/vol1-fundamentals/ch01/index.md","lastUpdated":null}'),s={name:"en/vol1-fundamentals/ch01/index.md"};function i(r,e,l,c,d,p){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="types-and-value-categories" tabindex="-1">Types and Value Categories <a class="header-anchor" href="#types-and-value-categories" aria-label="Permalink to &quot;Types and Value Categories&quot;">​</a></h1><p>The type system is one of the most core designs in C++—it determines how data is laid out in memory, what the compiler checks for you, and what operations you can perform on a piece of data. In this chapter, we start with fundamental data types, exploring what integers, floating-point numbers, characters, and booleans really are in C++. Then we discuss the implicit rules of type conversion that are easy to trip over, and revisit our old friend <code>const</code>. Finally, we get an initial taste of the concept of &quot;value categories,&quot; laying the groundwork for understanding move semantics later on.</p><h2 id="chapter-contents" tabindex="-1">Chapter Contents <a class="header-anchor" href="#chapter-contents" aria-label="Permalink to &quot;Chapter Contents&quot;">​</a></h2><ul><li><a href="./01-basic-types">Fundamental Data Types</a></li><li><a href="./02-type-conversion">Type Conversion</a></li><li><a href="./03-const-basics">Introduction to const</a></li><li><a href="./04-value-categories">Introduction to Value Categories</a></li></ul>',4)])])}const f=t(s,[["render",i]]);export{u as __pageData,f as default};
